=You are an expert sales qualification assistant.

Analyze this incoming lead and determine its quality.

Lead Information:

Name: {{ $('03 - Clean Lead Data').item.json.Name }}

Email: {{ $('03 - Clean Lead Data').item.json.Email }}

Company: {{ $('03 - Clean Lead Data').item.json.Company }}

Message: {{ $('03 - Clean Lead Data').item.json.Message }}

Source: {{ $('03 - Clean Lead Data').item.json.Source }}

Evaluate:
1. Buying intent
2. Company potential
3. Urgency
4. Fit for our service

Return ONLY valid JSON:

{
  "score": number,
  "priority": "High | Medium | Low",
  "reasoning": "short explanation",
  "recommended_action": "next sales step"
}

parameters.jsCode:
const response = $json.text || $json.output || $json.response;

if (!response) {
  throw new Error("No AI response received.");
}

const cleanJson = response
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

try {
  const aiData = JSON.parse(cleanJson);

  return {
    json: {
      ...$node["06 - Generate Lead ID"].json,
      aiScore: aiData.score,
      priority: aiData.priority,
      reasoning: aiData.reasoning,
      recommendedAction: aiData.recommended_action
    }
  };
} catch (error) {
  throw new Error("Invalid JSON returned by AI.");
}

const date = new Date();

const leadId = 
  "LEAD-" +
  date.getFullYear() +
  String(date.getMonth() + 1).padStart(2, "0") +
  String(date.getDate()).padStart(2, "0") +
  "-" +
  Math.floor(Math.random() * 9000 + 1000);

return {
  json: {
    ...$json,
    leadId
  }
};

let status = "Nurture";
let action = "Store Lead";
let assignedTeam = "Marketing";

switch ($json.priority) {
  case "High":
    status = "Sales Contact Required";
    action = "Notify Sales via Slack";
    assignedTeam = "Sales";
    break;

  case "Medium":
    status = "Follow Up Required";
    action = "Create Follow-up Task";
    assignedTeam = "Customer Success";
    break;

  case "Low":
    status = "Nurture";
    action = "Store Lead Only";
    assignedTeam = "Marketing";
    break;

  default:
    status = "Review Required";
    action = "Manual Review";
    assignedTeam = "Operations";
}

return {
  json: {
    ...$json,
    status,
    action,
    assignedTeam,
    processedAt: new Date().toISOString()
  }
};

